import{c as a,Q as o,j as t,m as r}from"./chunks/framework.BXc4yaFE.js";const p=JSON.parse('{"title":"Graph-of-Agents: A Graph-based Framework for Multi-Agent LLM Collaboration","description":"","frontmatter":{"url":"https://arxiv.org/abs/2604.17148","title":"Graph-of-Agents: A Graph-based Framework for Multi-Agent LLM Collaboration","archived_date":"2026-07-26T00:00:00.000Z","arxiv_id":2604.17148,"authors":["Sukwon Yun","Jie Peng","Pingzhi Li","Wendong Fan","Jie Chen","James Zou","Guohao Li","Tianlong Chen"],"domains":["cs.AI"],"pdf_path":"pdfs/2604.17148.pdf","published_date":"2026-04-18T00:00:00.000Z"},"headers":[],"relativePath":"research/papers/2026-04-18-goa-graph-of-agents-multi-agent-collaboration-2604-17148.md","filePath":"research/papers/2026-04-18-goa-graph-of-agents-multi-agent-collaboration-2604-17148.md","lastUpdated":1785909234000}'),n={name:"research/papers/2026-04-18-goa-graph-of-agents-multi-agent-collaboration-2604-17148.md"};function i(s,e,l,g,h,c){return o(),t("div",null,[...e[0]||(e[0]=[r('<h1 id="graph-of-agents-a-graph-based-framework-for-multi-agent-llm-collaboration" tabindex="-1">Graph-of-Agents: A Graph-based Framework for Multi-Agent LLM Collaboration <a class="header-anchor" href="#graph-of-agents-a-graph-based-framework-for-multi-agent-llm-collaboration" aria-label="Permalink to &quot;Graph-of-Agents: A Graph-based Framework for Multi-Agent LLM Collaboration&quot;">​</a></h1><p><strong>Authors</strong>: Sukwon Yun, Jie Peng, Pingzhi Li, Wendong Fan, Jie Chen, James Zou, Guohao Li, Tianlong Chen <strong>Published</strong>: April 18, 2026 <strong>Source</strong>: <a href="https://arxiv.org/abs/2604.17148" target="_blank" rel="noreferrer">https://arxiv.org/abs/2604.17148</a><strong>arXiv ID</strong>: 2604.17148 <strong>Categories</strong>: cs.AI <strong>Code</strong>: <a href="https://github.com/UNITES-Lab/GoA" target="_blank" rel="noreferrer">https://github.com/UNITES-Lab/GoA</a><strong>PDF</strong>: <a href="https://arxiv.org/abs/2604.17148" target="_blank" rel="noreferrer">research/papers/pdfs/2604.17148.pdf</a></p><blockquote><p><strong>Gotcha</strong>：本論文 arXiv 無 HTML 全文版本（<code>/html/2604.17148v1</code> 回 404，僅提供 PDF 與 TeX 原始碼），故無 <code>html</code> frontmatter 欄位；結構化摘要改由 PDF 全文（pymupdf4llm 擷取）交叉核對 WebFetch 摘要後撰寫。</p></blockquote><hr><h2 id="abstract-quoted" tabindex="-1">Abstract (quoted) <a class="header-anchor" href="#abstract-quoted" aria-label="Permalink to &quot;Abstract (quoted)&quot;">​</a></h2><blockquote><p>With an ever-growing zoo of LLMs and benchmarks, the need to orchestrate multiple models for improved task performance has never been more pressing. While frameworks like Mixture-of-Agents (MoA) attempt to coordinate LLMs, they often fall short in terms of (1) selecting relevant agents, (2) facilitating effective intra-agent communication, and (3) integrating responses efficiently. In this work, we propose Graph-of-Agents (GoA), a new graph-based framework for modeling multi-agent LLM communication. Our approach begins with node sampling, selecting only the most relevant agents by leveraging model cards that summarize each model&#39;s domain, task specialization, and other characteristics. Next, we construct edges between the selected agents by evaluating their responses against one another to determine relevance ordering. Directed message passing is then performed from highly relevant agents to less relevant ones to enhance their responses, followed by reverse message passing to refine the original responses of the more relevant agents. Finally, the updated responses are aggregated via graph-based pooling (e.g., max or mean pooling) to produce a single, unified answer. We evaluate GoA on diverse multi-domain benchmarks (MMLU, MMLU-Pro, GPQA) and domain-specific benchmarks (MATH, HumanEval, MedMCQA), with an agent pool of 6 LLMs spanning multiple domains. Surprisingly, GoA achieves superior performance using only 3 selected agents, outperforming recent multi-agent LLM baselines that utilize all 6 agents simultaneously. By adopting a graph structure, GoA offers both scalability and effectiveness through structured message passing-positioning it as a strong candidate for navigating the challenges of the ever-growing LLM zoo.</p></blockquote><hr><h2 id="結構化摘要" tabindex="-1">結構化摘要 <a class="header-anchor" href="#結構化摘要" aria-label="Permalink to &quot;結構化摘要&quot;">​</a></h2><h3 id="核心貢獻" tabindex="-1">核心貢獻 <a class="header-anchor" href="#核心貢獻" aria-label="Permalink to &quot;核心貢獻&quot;">​</a></h3><ul><li><strong>Node sampling</strong>：用 model card（domain / task specialization）做 Top-k 篩選相關 agent，過濾無關領域模型以防止 agent explosion</li><li><strong>Edge construction</strong>：讓被選 agent 互評彼此回應以決定 relevance ordering，建構 query-specific graph（而非固定拓撲）</li><li><strong>雙向 directed message passing</strong>：先由高相關度 agent 流向低相關度 agent（enhance 對方回應），再反向流回（refine 原始高相關度 agent 的回應）</li><li><strong>Graph pooling</strong>（max / mean）聚合最終答案；程式碼開源 <a href="https://github.com/UNITES-Lab/GoA" target="_blank" rel="noreferrer">https://github.com/UNITES-Lab/GoA</a></li></ul><h3 id="關鍵結果" tabindex="-1">關鍵結果 <a class="header-anchor" href="#關鍵結果" aria-label="Permalink to &quot;關鍵結果&quot;">​</a></h3><ul><li>6-LLM agent pool（7–8B 參數，涵蓋 General/Code/Math/Biomedical/Finance/Legal），Top-k=3；在 MMLU / MMLU-Pro / GPQA（多領域）與 MATH / HumanEval / MedMCQA（領域專用）上評測</li><li><strong>僅用 3 個 agent 即超越使用全部 6 個 agent 的 baseline</strong>（Debate / Self-Consistency / Refine / ReConcile / MoA / Self-MoA）：GoA-Max 平均最高，MMLU 79.18、MMLU-Pro 54.78、MedMCQA 60.04；GoA-Mean 在 GPQA 40.54、MATH 73.12、HumanEval 84.98 最佳</li><li>效率（MMLU-Pro）：相較 MoA 減少 LLM 呼叫數、token 用量與延遲，同時準確度更高</li><li>gpt-4o 規模擴展測試：GoA（3 agent）優於 DyLAN（8 個專門 agent）</li><li>消融：反轉 message-passing 方向造成最大性能下降（MMLU-Pro −2.60、GPQA −5.05）；top-k=2 限制多樣性、k=5 略降；邊閾值 τ=0.05 為最佳平衡點（過稀疏 τ=0.1/0.2 有害）</li></ul><h3 id="限制" tabindex="-1">限制 <a class="header-anchor" href="#限制" aria-label="Permalink to &quot;限制&quot;">​</a></h3><ul><li>論文未設獨立 Limitations 章節，Conclusion 僅重申貢獻，未討論失效模式</li><li>判斷弱點：top-k / τ 為手調超參數且敏感度高（消融顯示選擇顯著影響效果），跨任務自動調參未驗證</li><li>主力評測集中在 7–8B 開源模型 pool，僅一項 gpt-4o scaling-up 測試涵蓋專有模型，跨模型規模/家族的穩健性證據有限</li><li>Graph pooling 聚合策略（max/mean）相對簡單，對高衝突回應的處理未深入探討</li></ul><hr><h2 id="workspace-關聯-評估-非既成結論" tabindex="-1">Workspace 關聯（評估，非既成結論） <a class="header-anchor" href="#workspace-關聯-評估-非既成結論" aria-label="Permalink to &quot;Workspace 關聯（評估，非既成結論）&quot;">​</a></h2><ul><li>「用 model card 做 node sampling 過濾無關 agent」與 <code>core.md §PROPOSE 委派</code>（原 <code>graph.md §G3</code>）「fan-out 有上限」「brief 不清時越大越虧」同源：GoA 實證顯示 3 個相關 agent 勝過 6 個全量 agent，是「多不如準」的量化佐證。</li><li>Bidirectional message passing（先高→低相關度 enhance、再低→高相關度 refine 回饋）補強 <code>core.md §PROPOSE 委派</code>（原 <code>graph.md §G2</code>）「verify 靠視角互斥取勝」——提供一個可具體實作的雙向修正範式。⚠️ 論文的 agent 是同質 LLM pool 互評，非本 workspace 現行 parent↔child 單向委派拓撲，能否直接遷移未驗證。</li></ul>',17)])])}const m=a(n,[["render",i]]);export{p as __pageData,m as default};
